{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spf_mp_final AS WITH mapping_ref AS ( SELECT DISTINCT TRIM(join_key::STRING) AS join_key, \"Wh Type\" FROM ( SELECT \"Ticket No\" AS join_key, \"Wh Type\" FROM gs_bad_sheet1_final WHERE \"Ticket No\" IS NOT NULL UNION ALL SELECT \"Tracking No\" AS join_key, \"Wh Type\" FROM gs_bad_sheet1_final WHERE \"Tracking No\" IS NOT NULL UNION ALL SELECT \"Sale Order Code\" AS join_key, \"Wh Type\" FROM gs_bad_sheet1_final WHERE \"Sale Order Code\" IS NOT NULL ) QUALIFY ROW_NUMBER() OVER (PARTITION BY join_key ORDER BY \"Wh Type\") = 1 ) SELECT t.*, gs.\"Wh Type\", CASE WHEN UPPER(TRIM(t.status)) IN (\'APPROVED\', \'ACCEPT\', \'PAYMENT_COMPLETED\') THEN \'Approved\' WHEN UPPER(TRIM(t.status)) = \'NOT APPROVED\' THEN \'Rejected\' WHEN UPPER(TRIM(t.status)) IN (\'REJECTED\', \'REJECT\') THEN \'Rejected\' ELSE \'pending\' END AS final_status, CASE WHEN t.REJECTIONREASON ILIKE ANY (\'%same brand%\', \'%catalog%\', \'%not charged%\', \'%wrong size%\', \'%item_code%\', \'%claim_value%\', \'%cannot consider%\', \'%damage/used part%\') THEN \'Same brand equal price\' WHEN t.REJECTIONREASON ILIKE ANY (\'%out%tat%\', \'%tat breach%\', \'%beyond%tat%\') THEN \'Out tat\' WHEN t.REJECTIONREASON ILIKE \'%vms%\' THEN \'VMS\' WHEN t.REJECTIONREASON ILIKE \'%wfr%\' THEN \'WFR\' WHEN t.REJECTIONREASON ILIKE ANY (\'%video%\', \'%cctv%\', \'%360%\', \'%footage%\', \'%packing%\', \'%image%\', \'%six sided%\', \'%label%\') THEN \'video issue\' WHEN t.REJECTIONREASON ILIKE ANY (\'%tamper%\', \'%repack%\', \'%already opened%\') THEN \'tampered shipment\' WHEN t.REJECTIONREASON ILIKE \'%no response%\' THEN \'No response from seller\' WHEN t.REJECTIONREASON ILIKE ANY (\'%invalid%\', \'%not eligible%\', \'%duplicate%\', \'%insufficient%\', \'%wrong%\', \'%return delivered%\', \'%rto%\') THEN \'Invalid claim\' ELSE \'other\' END AS final_rejection_reason, CASE WHEN REGEXP_REPLACE(UPPER(TRIM(t.ISSUECATEGORY)), \'[_/-]\', \' \') ILIKE ANY (\'%FAKE%\', \'%DIFFERENT BRAND%\', \'%WRONG PRODUCT%\') THEN \'Fake\' WHEN REGEXP_REPLACE(UPPER(TRIM(t.ISSUECATEGORY)), \'[_/-]\', \' \') ILIKE ANY (\'%SHORT%\', \'%MISSING%\', \'%EMPTY BOX%\', \'%PARTIAL%\', \'%INCOMPLETE%\') THEN \'Short Qty\' WHEN REGEXP_REPLACE(UPPER(TRIM(t.ISSUECATEGORY)), \'[_/-]\', \' \') ILIKE ANY (\'%DAMAGE%\', \'%STAIN%\', \'%DEFECTIVE%\') THEN \'damage\' WHEN REGEXP_REPLACE(UPPER(TRIM(t.ISSUECATEGORY)), \'[_/-]\', \' \') ILIKE ANY (\'%WRONG RETURNS%\', \'%WPR%\', \'%SAME BRAND%\', \'%STICK%\') THEN \'wpr\' ELSE \'other\' END AS final_issuecategory, TO_CHAR(t.parsed_date, \'Mon-YYYY\') AS month_display, TO_CHAR(t.parsed_date, \'YYYY-MM\') AS month_order, YEAR(t.parsed_date) AS year FROM ( SELECT *, COALESCE( TRY_TO_TIMESTAMP_TZ(CREATEDON), TRY_TO_TIMESTAMP(CREATEDON), TRY_TO_DATE(CREATEDON, \'YYYY-MM-DD\'), CASE WHEN REGEXP_LIKE(CREATEDON, \'^\d{4}-\d{2}-\d{2}$\') THEN TRY_TO_DATE(SUBSTR(CREATEDON,1,4) || \'-\' || SUBSTR(CREATEDON,9,2) || \'-\' || SUBSTR(CREATEDON,6,2), \'YYYY-MM-DD\') END, TRY_TO_DATE(CREATEDON, \'DD-MM-YYYY\'), TRY_TO_DATE(CREATEDON, \'DD/MM/YYYY\'), TRY_TO_DATE(CREATEDON, \'MM-DD-YYYY\'), TRY_TO_DATE(CREATEDON, \'MM/DD/YYYY\'), TRY_TO_DATE(CREATEDON, \'DD-MON-YYYY\'), TRY_TO_DATE(CREATEDON, \'DD-MON-YY\'), DATEADD(DAY, TRY_TO_NUMBER(CREATEDON), \'1899-12-30\') ) AS parsed_date FROM spf_mp ) t LEFT JOIN mapping_ref gs ON gs.join_key = TRIM(COALESCE(t.TICKETID, t.TRACKINGID, t.RETURNTRACKINGID)::STRING);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            